@props(['sidebar' => false])
<div class="sbg-account sbg-v24-account {{ $sidebar ? 'sbg-v24-account-sidebar' : '' }}" x-data="{ accountOpen: false }" @click.outside="accountOpen = false" @keydown.escape.stop.prevent="accountOpen = false; $refs.accountTrigger.focus()">
    <button x-ref="accountTrigger" type="button" class="sbg-account-toggle" @click="accountOpen = !accountOpen; if (accountOpen) $nextTick(() => $refs.accountLogout.focus())" @keydown.arrow-down.prevent="accountOpen = true; $nextTick(() => $refs.accountLogout.focus())" :aria-expanded="accountOpen" aria-haspopup="true" aria-label="Menu akun {{ auth()->user()->name }}"><span class="sbg-avatar">{{ mb_strtoupper(mb_substr(auth()->user()->name, 0, 1)) }}</span><span class="sbg-account-name"><strong>{{ auth()->user()->name }}</strong><small>{{ auth()->user()->region ?? 'Pusat' }}</small></span><span class="sbg-account-chevron" aria-hidden="true">⌄</span></button>
    <div x-cloak x-show="accountOpen" x-transition:enter="sbg-v24-menu-enter" x-transition:enter-start="sbg-v24-menu-hidden" x-transition:enter-end="sbg-v24-menu-visible" class="sbg-account-menu sbg-v24-account-menu" @keydown.tab="accountOpen = false">
        <div class="sbg-v24-account-profile"><span class="sbg-avatar">{{ mb_strtoupper(mb_substr(auth()->user()->name, 0, 1)) }}</span><div><strong>{{ auth()->user()->name }}</strong><p>{{ auth()->user()->region ?? 'Pusat' }}</p><small>{{ auth()->user()->isSuperAdmin() ? 'Super Admin' : (auth()->user()->isKepalaDapur() ? 'Kepala Dapur' : 'Admin') }}</small></div></div>
        <button x-ref="accountLogout" type="button" @click="accountOpen = false; isLogoutModalOpen = true; navOpen = false"><x-sbg.icon name="logout"/><span>Keluar dari akun<small>Akhiri sesi pada perangkat ini</small></span><span aria-hidden="true">→</span></button>
    </div>
</div>
